import { NextRequest, NextResponse, after } from 'next/server';
import { createClient } from '@supabase/supabase-js';
import { parseBody, messagesSchema } from '@/lib/validation';
import { buildSystemPrompt, DEFAULT_IDENTITY, type AvatarIdentity } from '@/lib/avatar/identity';
import { checkLimit } from '@/lib/rate-limit';
import { anthropicDispatcher } from '@/lib/anthropic-dispatcher';

export async function GET(req: NextRequest) {
  const token = req.headers.get('authorization')?.replace('Bearer ', '');
  if (!token) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

  // Клиент с правами пользователя (RLS работает)
  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    { global: { headers: { Authorization: `Bearer ${token}` } } }
  );

  const { data: { user }, error: userErr } = await supabase.auth.getUser(token);
  if (userErr || !user) return NextResponse.json({ error: 'Invalid token' }, { status: 401 });

  const matchId = req.nextUrl.searchParams.get('matchId');
  if (!matchId) return NextResponse.json({ error: 'matchId is required' }, { status: 400 });

  // Проверить, что пользователь — участник мэтча
  const { data: match, error: matchErr } = await supabase
    .from('matches')
    .select('id, founder1_id, founder2_id')
    .eq('id', matchId)
    .single();

  if (matchErr || !match) {
    return NextResponse.json({ error: 'Match not found' }, { status: 404 });
  }

  // Найти founder_profiles для текущего пользователя
  const { data: myProfile } = await supabase
    .from('founder_profiles')
    .select('id')
    .eq('user_id', user.id)
    .single();

  if (!myProfile) {
    return NextResponse.json({ error: 'Profile not found' }, { status: 404 });
  }

  if (myProfile.id !== match.founder1_id && myProfile.id !== match.founder2_id) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
  }

  // ?after=<ISO created_at> — инкрементальная подгрузка: только сообщения новее.
  // Без параметра возвращаем всё (начальная загрузка, обратная совместимость).
  const afterTs = req.nextUrl.searchParams.get('after');

  let query = supabase
    .from('messages')
    .select('*')
    .eq('match_id', matchId)
    .order('created_at', { ascending: true });

  if (afterTs) {
    query = query.gt('created_at', afterTs);
  }

  const { data: messages, error: msgsErr } = await query;

  if (msgsErr) {
    return NextResponse.json({ error: msgsErr.message }, { status: 500 });
  }

    // Добавляем флаг is_me, чтобы клиент точно знал, чье это сообщение
  const messagesWithFlags = (messages || []).map(m => ({
    ...m,
    is_me: m.sender_id === myProfile.id,
  }));

  return NextResponse.json({ messages: messagesWithFlags, myFounderId: myProfile.id });
}
